<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\QuestionLearning;
use App\Domain\QuestionLearning\Entity\QuestionProblemReport;use App\Domain\QuestionLearning\Enum\ProblemReportCategory;use App\Domain\QuestionLearning\Enum\ProblemReportStatus;use App\Domain\QuestionLearning\Repository\QuestionProblemReportRepositoryInterface;use App\Infrastructure\Persistence\Doctrine\QuestionLearning\Entity\QuestionProblemReportEventRecord;use App\Infrastructure\Persistence\Doctrine\QuestionLearning\Entity\QuestionProblemReportRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineQuestionProblemReportRepository implements QuestionProblemReportRepositoryInterface { public function __construct(private readonly EntityManagerInterface $entityManager) {} public function save(QuestionProblemReport $report): void { $record = new QuestionProblemReportRecord(); $record->id = $report->id; $record->questionId = $report->questionId; $record->reportedBy = $report->reportedBy; $record->category = $report->category->value; $record->description = $report->description; $record->status = $report->status()->value; $record->createdAt = $report->createdAt; $record->updatedAt = $report->updatedAt(); $this->entityManager->persist($record); $this->entityManager->flush(); } public function appendStatusEvent(string $reportId, string $actorUserId, ?ProblemReportStatus $previous, ProblemReportStatus $next, \DateTimeImmutable $occurredAt): void { $record = new QuestionProblemReportEventRecord(); $record->id = $this->uuid(); $record->reportId = $reportId; $record->actorUserId = $actorUserId; $record->eventType = $previous === null ? 'CREATED' : 'STATUS_CHANGED'; $record->previousStatus = $previous?->value; $record->nextStatus = $next->value; $record->occurredAt = $occurredAt; $this->entityManager->persist($record); $this->entityManager->flush(); } public function countOpenForUserQuestion(string $userId, string $questionId): int { return (int) $this->entityManager->createQueryBuilder()->select('COUNT(report.id)')->from(QuestionProblemReportRecord::class, 'report')->where('report.reportedBy = :userId')->andWhere('report.questionId = :questionId')->andWhere('report.status = :status')->setParameter('userId', $userId)->setParameter('questionId', $questionId)->setParameter('status', ProblemReportStatus::OPEN->value)->getQuery()->getSingleScalarResult(); } private function uuid(): string { $bytes = random_bytes(16); $bytes[6] = chr((ord($bytes[6]) & 15) | 64); $bytes[8] = chr((ord($bytes[8]) & 63) | 128); return vsprintf('%s%s-%s-%s-%s-%s%s%s', str_split(bin2hex($bytes), 4)); } }
